import unittest
from raw_minute_core import *
from test_raw_minute_core import manifest,envelope,KEY
class ReviewRegressions(unittest.TestCase):
 def test_null_empty_or_nonstring_page_urls(self):
  for value in (None,'',False,0,[],{}):
   for page in (1,2,3,4):
    with self.subTest(value=value,page=page),self.assertRaises(SourceError):validate_page_url(value,manifest(),page)
 def test_all_failure_acknowledgement_exceptions_are_unknown_and_sanitized(self):
  m=manifest();r=Reservation(m['request_sha256'],first_url(m),1,'11111111-1111-4111-8111-111111111111',MAX_BYTES,2000,True,3,1)
  for response in (HttpResponse(403,b''),HttpResponse(200,envelope(),True),HttpResponse(200,b'bad')):
   calls=[]
   def failure(*a):calls.append('failure');raise RuntimeError('sensitive-test-detail')
   def transport(*a):calls.append('transport');return response
   def commit(*a):calls.append('commit')
   with self.subTest(response=response),self.assertRaisesRegex(UnknownOutcome,'^FAILURE_RECORD_OUTCOME_REQUIRES_RECONCILIATION$') as ctx:
    acquire_page(m,r,KEY,transport,commit,failure,now=lambda:1000)
   self.assertNotIn('sensitive-test-detail',str(ctx.exception));self.assertEqual(calls,['transport','failure'])
if __name__=='__main__':unittest.main(verbosity=2)

