CREATE FUNCTION population_top3000_202608_202609_v1.raw_minute_manifest_validate_v1(p_manifest_text text) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path='pg_catalog' AS $fn$
DECLARE m jsonb;canonical_text text;unsigned_text text;keys text[];symbol text;start_ms bigint;end_ms bigint;
BEGIN
IF p_manifest_text IS NULL OR octet_length(p_manifest_text) NOT BETWEEN 1 AND 4096 THEN RAISE EXCEPTION 'RAW_MANIFEST_TEXT_REQUIRED';END IF;
BEGIN m:=p_manifest_text::jsonb;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'RAW_MANIFEST_JSON_INVALID';END;
IF jsonb_typeof(m) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'RAW_MANIFEST_SHAPE';END IF;
SELECT array_agg(key ORDER BY key) INTO keys FROM json_each(p_manifest_text::json);
IF keys IS DISTINCT FROM ARRAY['adjusted','candidate_company_id','cohort_sha256','end_exclusive_ms','limit','max_pages','max_response_bytes','multiplier','normalized_price_activation','qualification','request_sha256','schema','sort','start_ms','symbol','timespan']::text[] THEN RAISE EXCEPTION 'RAW_MANIFEST_SHAPE';END IF;
IF m->>'schema' IS DISTINCT FROM 'RAW_MINUTE_MONTH_V1' OR m->>'cohort_sha256' IS DISTINCT FROM '2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' OR jsonb_typeof(m->'candidate_company_id') IS DISTINCT FROM 'string' OR coalesce(m->>'candidate_company_id','')!~'^CIK:[0-9]{10}$' OR jsonb_typeof(m->'symbol') IS DISTINCT FROM 'string' OR coalesce(m->>'symbol','')!~'^[A-Za-z0-9][A-Za-z0-9.\^-]{0,31}$' THEN RAISE EXCEPTION 'RAW_MANIFEST_SCOPE';END IF;
IF EXISTS(SELECT 1 FROM unnest(ARRAY['start_ms','end_exclusive_ms','multiplier','limit','max_pages','max_response_bytes']) k WHERE jsonb_typeof(m->k) IS DISTINCT FROM 'number' OR coalesce(m->>k,'')!~'^[0-9]+$') THEN RAISE EXCEPTION 'RAW_MANIFEST_INTEGER_FIELDS';END IF;
start_ms:=(m->>'start_ms')::bigint;end_ms:=(m->>'end_exclusive_ms')::bigint;symbol:=m->>'symbol';
IF NOT ((start_ms=1785556800000 AND end_ms=1788235200000) OR (start_ms=1788235200000 AND end_ms=1790827200000)) THEN RAISE EXCEPTION 'RAW_MANIFEST_WINDOW';END IF;
IF m->>'multiplier' IS DISTINCT FROM '1' OR m->>'timespan' IS DISTINCT FROM 'minute' OR m->'adjusted' IS DISTINCT FROM 'false'::jsonb OR m->>'sort' IS DISTINCT FROM 'asc' OR m->>'limit' IS DISTINCT FROM '50000' OR (m->>'max_pages')::numeric NOT BETWEEN 1 AND 4 OR (m->>'max_response_bytes')::numeric NOT BETWEEN 1 AND 8388608 THEN RAISE EXCEPTION 'RAW_MANIFEST_BOUNDS';END IF;
IF m->>'qualification' IS DISTINCT FROM 'RAW_PROVIDER_SOURCE_ONLY_IDENTITY_LIFECYCLE_NOT_CERTIFIED' OR m->'normalized_price_activation' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'RAW_MANIFEST_QUALIFICATION';END IF;
-- All admitted strings are ASCII with no arbitrary free-text values. This exact
-- compact sorted serialization matches Python canonical(), unlike jsonb::text.
SELECT '{'||string_agg(to_json(key)::text||':'||value::text,',' ORDER BY key)||'}' INTO canonical_text FROM jsonb_each(m);
SELECT '{'||string_agg(to_json(key)::text||':'||value::text,',' ORDER BY key)||'}' INTO unsigned_text FROM jsonb_each(m) WHERE key<>'request_sha256';
IF encode(sha256(convert_to(unsigned_text,'UTF8')),'hex') IS DISTINCT FROM m->>'request_sha256' THEN RAISE EXCEPTION 'RAW_MANIFEST_CANONICAL_HASH';END IF;
RETURN jsonb_build_object('manifest',m,'original_manifest_text',p_manifest_text,'canonical_manifest_text',canonical_text,'unsigned_manifest_text',unsigned_text,'request_sha256',m->>'request_sha256','manifest_text_sha256',encode(sha256(convert_to(p_manifest_text,'UTF8')),'hex'),'first_url','https://api.massive.com/v2/aggs/ticker/'||replace(symbol,'^','%5E')||'/range/1/minute/'||start_ms||'/'||(end_ms-1)||'?adjusted=false&sort=asc&limit=50000','source_admitted',false,'identity_lifecycle_qualified',false,'normalized_price_activation',false,'family_accepted',false);
END $fn$;
REVOKE ALL ON FUNCTION population_top3000_202608_202609_v1.raw_minute_manifest_validate_v1(text) FROM PUBLIC,anon,authenticated;

